export const FOUC_SCRIPT = `(function(){var mode='dark',theme='xoxd';try{var stored=localStorage.getItem('color-mode');if(stored==='light'||stored==='dark'){mode=stored}else if(stored==='system'){mode=window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}var saved=localStorage.getItem('skeleton-theme');if(['xoxd','scaffold','pine','rose','catppuccin','trans'].indexOf(saved)!==-1){theme=saved}}catch(e){}document.documentElement.setAttribute('data-mode',mode);document.documentElement.style.colorScheme=mode;document.documentElement.setAttribute('data-theme',theme)})();`;
